const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s)), esc=x=>String(x==null?"":x).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const today=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}, initials=x=>String(x||"AS").split(/\s+/).slice(0,2).map(y=>y[0]||"").join("").toUpperCase();
const patient=id=>S.data.state.patients.find(x=>x.id===id), enc=id=>S.data.state.encounters.find(x=>x.id===id), pname=id=>patient(id)?.name||"Unknown patient";
function datefmt(x){return x?new Date(x+"T00:00:00").toLocaleDateString(S.locale==="hi"?"hi-IN":"en-IN",{day:"numeric",month:"short",year:"numeric"}):t("notDocumented");}
function toast(m,bad=false){const e=document.createElement("div");e.className="toast"+(bad?" error":"");e.textContent=m;$("#toasts").append(e);setTimeout(()=>e.remove(),3500);}
function applyLocale(){const map=I18N[S.locale]||I18N.en;$$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(map[key]!==undefined)el.innerHTML=map[key];});const select=$("#ui-language");if(select)select.value=S.locale;document.documentElement.lang=S.locale==="hi"?"hi":"en";T.dashboard=t("overview");T.patients=t("patients");T.encounters=t("encounters");T.followups=t("followups");T.reports=t("reports");T.workspace=t("workspace");$("#page-title").textContent=T[S.page]||T.dashboard;document.title="Asha Sahayak | "+T[S.page];}
function applyTheme(){document.body.dataset.theme=S.theme;const b=$("#theme-toggle");if(b){b.innerHTML=icon(S.theme==="dark"?"sun":"moon");b.title=S.theme==="dark"?"Light mode":"Dark mode";b.setAttribute("aria-label",b.title);}localStorage.setItem("asha-sahayak-theme",S.theme);}
function observeReveals(){const nodes=$$('[data-reveal]:not(.revealed)');if(!nodes.length)return;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||!window.IntersectionObserver){nodes.forEach(x=>x.classList.add("revealed"));return;}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("revealed");observer.unobserve(entry.target);}}),{threshold:.08});nodes.forEach(x=>observer.observe(x));}
async function api(path,data){
 let r;
 try{r=await fetch("/api"+path,data===undefined?{cache:"no-store"}:{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data),cache:"no-store"});}
 catch(error){S.online=false;if(S.data)render();throw error;}
 S.online=r.status<500;if(!S.online&&S.data)render();
 if(!r.ok&&r.headers.get("content-type")?.includes("application/json"))throw Error((await r.json()).error||"Request failed");
 return r;
}
