let modalReturnFocus=null;
function modal(title,body){modalReturnFocus=document.activeElement;$("#modal-title").textContent=title;$("#modal-body").innerHTML=body;bindAccessibility($("#modal-body"));$("#modal-backdrop").classList.remove("hidden");$("#modal-body").querySelector("input:not([type=hidden]),select,textarea,button")?.focus();}
function closeModal(){$("#modal-backdrop").classList.add("hidden");S.afterPatientCreate=false;if(modalReturnFocus?.isConnected)modalReturnFocus.focus();modalReturnFocus=null;}
let controlLabelId=0;
function bindAccessibility(root){
 if(!root)return;
 root.querySelectorAll(".field").forEach(group=>{const label=group.querySelector(":scope > label"),control=group.querySelector(":scope > input, :scope > select, :scope > textarea");if(!label||!control)return;if(!control.id){do{control.id="field-control-"+(++controlLabelId);}while(document.getElementById(control.id)&&document.getElementById(control.id)!==control);}label.htmlFor=control.id;});
 root.querySelectorAll(".clinical").forEach(card=>{const control=card.querySelector(".field-value"),label=card.querySelector(".clinical-title b");if(control&&label){if(!label.id)label.id="clinical-label-"+control.dataset.field;control.setAttribute("aria-labelledby",label.id);}});
 const search=root.querySelector("#enc-search");if(search)search.setAttribute("aria-label",t("searchPatients"));
 ["#enc-filter","#follow-filter"].forEach(selector=>{const filter=root.querySelector(selector);if(filter)filter.setAttribute("aria-label",t("filterStatus"));});
}
