async function openWorkspace(id,pid){
 S.geminiConsent=false;if(S.audioUrl)URL.revokeObjectURL(S.audioUrl);S.audioUrl=null;S.audioFile=null;S.audioReady=false;S.speechStatus="";S.speechStatusType="";
 if(id){const e=enc(id);if(!e)return toast("Encounter not found.",true);S.draft=JSON.parse(JSON.stringify(e));}
 else S.draft={id:null,patient_id:pid||S.data.state.patients[0].id,date:today(),type:"Community health visit",language:"Hindi",transcript:"",transcription_mode:"Manual entry",status:"draft",fields:Object.fromEntries(F.map(([k])=>[k,{value:"",source:"",review:"unreviewed",origin:"worker"}]))};
 closeModal();S.page="workspace";$("#page-title").textContent=T.workspace;$$(".nav-link[data-page]").forEach(x=>x.classList.toggle("active",x.dataset.page==="encounters"));render();
}
function readDraft(){
 const d=S.draft;if(!d)return d;
 const t=$("#transcript");if(t)d.transcript=t.value;const p=$("#ws-patient");if(p)d.patient_id=p.value;const dt=$("#ws-date");if(dt)d.date=dt.value||today();const ty=$("#ws-type");if(ty)d.type=ty.value;const l=$("#ws-language");if(l)d.language=l.value;
 $$(".field-value").forEach(x=>{if(d.fields[x.dataset.field])d.fields[x.dataset.field].value=x.value;});return d;
}
function addQueue(d){let q=[];try{q=JSON.parse(localStorage.getItem("asha-sahayak-pending-drafts")||"[]");}catch{}const i=q.findIndex(x=>x.id===d.id);if(i>=0)q[i]=d;else q.push(d);localStorage.setItem("asha-sahayak-pending-drafts",JSON.stringify(q));S.queue=q;}
function calc(s){const d=today();return{today:s.encounters.filter(e=>e.date===d).length,drafts:s.encounters.filter(e=>e.status==="draft").length,review:s.encounters.filter(e=>e.status==="review").length,due:s.followups.filter(f=>f.status==="pending"&&f.due_date<=d).length,overdue:s.followups.filter(f=>f.status==="pending"&&f.due_date<d).length};}
async function saveDraft(quiet=false){
 const d=readDraft();if(!d)return false;
 try{const o=await(await api("/encounters",d)).json();Object.assign(d,o.encounter);S.data.state=o.state;S.data.metrics=calc(o.state);S.draft=d;if(!quiet)toast(t("draftSaved"));render();return true;}
 catch(e){addQueue(d);if(!quiet)toast("Server unavailable. Draft saved in this browser only; retry later.",true);render();return false;}
}
function mergeSuggestions(d,suggested){d.fields=d.fields||{};for(const [key] of F){const old=d.fields[key];if(old&&['literal_match','gemini_suggestion'].includes(old.origin)&&old.review==='unreviewed'&&!suggested[key])delete d.fields[key];}for(const [key,value] of Object.entries(suggested)){if(!F.some(([known])=>known===key))continue;const old=d.fields[key];const emptyWorker=old&&old.origin==='worker'&&old.review==='unreviewed'&&!String(old.value||'').trim()&&!String(old.source||'').trim();if(!old||emptyWorker||(old&&['literal_match','gemini_suggestion'].includes(old.origin)&&old.review==='unreviewed'))d.fields[key]=value;}}
async function extractFields(quiet=false){
 const d=readDraft();if(!d.transcript.trim()){if(!quiet)toast(t("noTranscript"),true);return 0;}
 try{const response=await fetch("/api/extract",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({transcript:d.transcript}),cache:"no-store"});const o=await response.json();if(!response.ok)throw Error(o.error||"Could not match transcript phrases.");const suggested=o.fields||{};mergeSuggestions(d,suggested);d.extraction_mode=o.mode;const count=Object.keys(suggested).length;render();if(!quiet)toast(count?t("foundFields")+count:t("noPhrases"),!count);return count;}
 catch(e){if(!quiet)toast(e.message,true);return 0;}
}
async function approve(){
 let d=readDraft();if(!d.id){if(!await saveDraft(true))return;d=S.draft;}
 try{const o=await(await api("/encounters/"+encodeURIComponent(d.id)+"/approve",{})).json();S.data.state=o.state;S.data.metrics=calc(o.state);S.draft=o.encounter;toast(t("finalize"));render();}
 catch(e){toast(e.message,true);}
}
