function filterFollow(){
 const f=$("#follow-filter")?.value||"all";$$("[data-follow]").forEach(row=>{const x=S.data.state.followups.find(y=>y.id===row.dataset.follow),over=x.status==="pending"&&x.due_date<today();row.hidden=!(f==="all"||(f==="pending"&&x.status==="pending")||(f==="completed"&&x.status==="completed")||(f==="overdue"&&over));});
}
document.addEventListener("click",async ev=>{
 const t=ev.target.closest("button,a");if(!t)return;
 if(!S.data&&t.dataset.action!=="retry-database")return;
 if(t.dataset.page){ev.preventDefault();nav(t.dataset.page);return;}
 if(t.dataset.nav){nav(t.dataset.nav);return;}
 if(t.dataset.open){closeModal();await openWorkspace(t.dataset.open);return;}
 if(t.dataset.editProfile){patientModal(t.dataset.editProfile);return;}
 if(t.dataset.editFollowup){editFollowupModal(t.dataset.editFollowup);return;}
 if(t.dataset.profile){profile(t.dataset.profile);return;}
 if(t.dataset.selectReport){S.reportId=t.dataset.selectReport;nav("reports");return;}
 if(t.dataset.review&&S.draft){const f=S.draft.fields[t.dataset.field];f.review=t.dataset.review;if(f.review==="unknown")f.value="Not documented";else if(f.review==="edited")f.value=$('[data-field="'+t.dataset.field+'"]').value;render();return;}
 if(t.dataset.complete){completeModal(t.dataset.complete);return;}
 const a=t.dataset.action;
 if(a==="new-patient")patientModal();
 else if(a==="new-encounter"){const p=t.dataset.patient;newEncounterModal();if(p&&$("#choose-patient"))$("#choose-patient").value=p;}
 else if(a==="new-followup")followupModal();
 else if(a==="close")closeModal();
 else if(a==="create-patient")await createPatient();
 else if(a==="update-patient")await updatePatient(t.dataset.id);
 else if(a==="start")await openWorkspace("",$("#choose-patient").value);
 else if(a==="save")await saveDraft();
 else if(a==="extract")await extractFields();
 else if(a==="approve")await approve();
 else if(a==="amend")amendModal();
 else if(a==="amend-confirm")await amend();
 else if(a==="create-followup")await createFollowup();
 else if(a==="update-followup")await updateFollowup(t.dataset.id);
 else if(a==="complete-confirm")await completeTask(t.dataset.id);
 else if(a==="pdf")await downloadPDF();
 else if(a==="json")downloadJSON();
 else if(a==="retry")await retryQueue();
 else if(a==="retry-database")await connectDatabase();
 else if(a==="transcribe-audio")await transcribeUploadedAudio();
  else if(a==="clear"){if($("#transcript"))$("#transcript").value="";S.draft.transcript="";if($("#trans-count"))$("#trans-count").textContent="0 characters";}
});
