 $("#view").innerHTML='<div class="card db-setup-card"><h2>'+t("localError")+'</h2><p>'+t("databaseHelp")+'</p><code>'+esc(error.message||t("localError"))+'</code><button class="secondary" data-action="retry-database">'+t("retryDatabase")+'</button></div>';
